CREATE TABLE "AttendanceJustification" ("id" TEXT NOT NULL, "businessDay" TEXT NOT NULL, "personId" TEXT NOT NULL, "entryScanId" TEXT NOT NULL, "reason" TEXT NOT NULL, "active" BOOLEAN NOT NULL DEFAULT true, "createdBy" TEXT NOT NULL, "updatedBy" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "AttendanceJustification_pkey" PRIMARY KEY ("id"), CONSTRAINT "AttendanceJustification_personId_fkey" FOREIGN KEY ("personId") REFERENCES "Person"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE UNIQUE INDEX "AttendanceJustification_businessDay_personId_key" ON "AttendanceJustification"("businessDay", "personId");
CREATE INDEX "AttendanceJustification_businessDay_active_idx" ON "AttendanceJustification"("businessDay", "active");
CREATE TABLE "AttendanceJustificationEvent" ("id" TEXT NOT NULL, "justificationId" TEXT NOT NULL, "entryScanId" TEXT NOT NULL, "action" TEXT NOT NULL, "reason" TEXT NOT NULL, "actorId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "AttendanceJustificationEvent_pkey" PRIMARY KEY ("id"), CONSTRAINT "AttendanceJustificationEvent_justificationId_fkey" FOREIGN KEY ("justificationId") REFERENCES "AttendanceJustification"("id") ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE INDEX "AttendanceJustificationEvent_justificationId_createdAt_idx" ON "AttendanceJustificationEvent"("justificationId", "createdAt");
